SELECT amount_bucket, total_amount, unique_merchants FROM (SELECT CASE WHEN amount >= 3300 THEN 'high' WHEN amount >= 1400 THEN 'mid' ELSE 'low' END AS amount_bucket, SUM(amount) AS total_amount, COUNT(DISTINCT amount) AS unique_merchants FROM transactions WHERE HOUR(txn_time) BETWEEN 10 AND 16 GROUP BY CASE WHEN amount >= 3300 THEN 'high' WHEN amount >= 1400 THEN 'mid' ELSE 'low' END) AS x WHERE unique_merchants > 4 ORDER BY amount_bucket;
